from collections import deque

def assignEdgeWeights(edges, queries):
    MOD = 10**9 + 7
    n = len(edges) + 1
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    LOG = max(1, n.bit_length())
    up = [[1] * (n + 1) for _ in range(LOG)]  # up[k][v]: 2^k-th ancestor (root points to itself)
    depth = [-1] * (n + 1)
    depth[1] = 0
    dq = deque([1])
    while dq:
        u = dq.popleft()
        for v in adj[u]:
            if depth[v] == -1:
                depth[v] = depth[u] + 1
                up[0][v] = u
                dq.append(v)

    for k in range(1, LOG):
        prev, cur = up[k - 1], up[k]
        for v in range(1, n + 1):
            cur[v] = prev[prev[v]]

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        diff = depth[u] - depth[v]
        for k in range(LOG):
            if (diff >> k) & 1:
                u = up[k][u]
        if u == v:
            return u
        for k in range(LOG - 1, -1, -1):
            if up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = pow2[i - 1] * 2 % MOD

    ans = []
    for u, v in queries:
        d = depth[u] + depth[v] - 2 * depth[lca(u, v)]
        ans.append(0 if d == 0 else pow2[d - 1])
    return ans
